package com.example.dsatracker.model;import jakarta.persistence.*;import lombok.*;import java.time.LocalDateTime;import java.util.HashSet;import java.util.Set;@Entity@Table(name = "tags")@Getter@Setter@NoArgsConstructor@AllArgsConstructor@Builderpublic class Tag {    @Id    @GeneratedValue(strategy = GenerationType.IDENTITY)    private Long id;    @Column(nullable = false, unique = true, length = 100)    private String name;    @Column(length = 500)    private String description;    @Column(nullable = false, updatable = false)    private LocalDateTime createdAt;    @ManyToMany(mappedBy = "tags")    @Builder.Default    private Set<Problem> problems = new HashSet<>();    @PrePersist    public void onCreate() {        createdAt = LocalDateTime.now();    }}